    AppointmentFixture f;auto accepted=f.accept();f.leave();PersonalAppointmentAttendanceCatalog attendance;attendance.policies.push_back({"private_visit",1});PersonalAppointmentAttendanceRead read{f.common,f.interaction,f.ic,f.appointments,f.appointment_state};TravelCatalog travel;travel.places.insert("market",{"town",{"street"}});travel.places.insert("street",{"town",{"market"}});
