    DecisionProposal base;base.subject_id="sender";base.plan_id="plan:sender:1";auto transition=std::make_shared<DirectorTransition>();transition->expected_revision=f.common.revision();transition->next_review_tick=f.common.tick()+10;transition->template_id="await_adjustment";base.transition=transition;
    auto early=propose_personal_appointment_attendance(read,attendance,travel,view,base);require(early.ok&&early.value&&!early.value->command&&early.value->transition->wait_reason=="AppointmentWindowNotOpen","early actual arrival stays available without Wait Action");require(base.transition->template_id=="await_adjustment"&&base.transition->next_review_tick==f.common.tick()+10,"proposal does not mutate borrowed original transition");require(early.value->transition->next_review_tick==f.common.tick()+1,"one next-halfday review does not miss original window");
